// Welcome Link: Spanish page generator.
// Renders the Spanish copy (T.es) of the bilingual pages into real HTML at /es/ so search engines
// and AI assistants can read the Spanish version without running JavaScript. The toggle still works
// in place on every page. Run after editing index.html or websites/index.html:
//
//   node build-es.js
//
// The es/ files are generated. Do not edit them by hand.
const fs = require('fs'), path = require('path');
const root = __dirname, B = 'https://thewelcomelink.com';

const PAGES = [
  { src: 'index.html', out: 'es/index.html', en: '/', es: '/es/',
    title: 'The Welcome Link · Guías de bienvenida y sitios web, Puerto Escondido',
    desc: 'Guías de bienvenida digitales para anfitriones de rentas vacacionales, hechas por nosotros en 48 horas. Del mismo estudio en Puerto Escondido: sitios web de reserva directa y Villa Reels.' },
  { src: 'websites/index.html', out: 'es/websites/index.html', en: '/websites/', es: '/es/websites/' }
];
// Internal links that have a Spanish twin.
const LINKS = { '/': '/es/', '/websites/': '/es/websites/' };

function extractObject(html, name) {
  const m = html.match(new RegExp('const ' + name + ' = (\\{[\\s\\S]*?\\n  \\});'));
  if (!m) throw new Error('Could not find ' + name);
  return new Function('return ' + m[1])();
}
// Replace the inner HTML of every element carrying data-i18n, matching nested tags of the same name.
function renderI18n(html, dict) {
  const open = /<([a-zA-Z0-9]+)\b[^>]*\sdata-i18n="([^"]+)"[^>]*>/g;
  let out = '', last = 0, m;
  while ((m = open.exec(html))) {
    const [tag, name, key] = [m[0], m[1], m[2]];
    const start = m.index + tag.length;
    const re = new RegExp('<(/?)' + name + '\\b[^>]*>', 'g'); re.lastIndex = start;
    let depth = 1, t, end = -1;
    while ((t = re.exec(html))) { depth += t[1] ? -1 : 1; if (!depth) { end = t.index; break; } }
    if (end < 0) throw new Error('Unclosed <' + name + '> for ' + key);
    if (dict[key] === undefined) continue;
    out += html.slice(last, start) + dict[key];
    last = end; open.lastIndex = end;
  }
  return out + html.slice(last);
}
const esc = s => s.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
const wa = text => 'https://wa.me/529542061152?text=' + encodeURIComponent(text);

for (const p of PAGES) {
  let h = fs.readFileSync(path.join(root, p.src), 'utf8');
  const T = extractObject(h, 'T');
  let title = p.title, desc = p.desc, waText = null;
  if (/const META = /.test(h)) { const M = extractObject(h, 'META'); title = M.es.title; desc = M.es.desc; waText = M.es.wa; }

  h = renderI18n(h, T.es);
  h = h.replace('<html lang="en">', '<html lang="es">');
  h = h.replace(/<title>[^<]*<\/title>/, '<title>' + title + '</title>');
  h = h.replace(/(<meta name="description" content=")[^"]*/, '$1' + esc(desc));
  h = h.replace(/(<meta property="og:description" content=")[^"]*/, '$1' + esc(desc));
  h = h.replace(/(<meta property="og:title" content=")[^"]*/, '$1' + esc(title));
  h = h.replace(/(<meta property="og:url" content=")[^"]*/, '$1' + B + p.es);
  h = h.replace(/(<link rel="canonical" href=")[^"]*/, '$1' + B + p.es);
  h = h.replace('<meta property="og:locale" content="en_US">\n<meta property="og:locale:alternate" content="es_MX">',
                '<meta property="og:locale" content="es_MX">\n<meta property="og:locale:alternate" content="en_US">');
  // Spanish WhatsApp prefills in the static HTML.
  h = h.replace(/href="[^"]*"([^>]*?)data-wa-es="([^"]*)"/g, (all, mid, text) =>
    'href="' + wa(text.replace(/&quot;/g, '"')) + '"' + mid + 'data-wa-es="' + text + '"');
  if (waText) h = h.replace(/(class="[^"]*js-wa[^"]*" href=")[^"]*/g, '$1' + wa(waText));
  // Internal links to their Spanish twins.
  h = h.replace(/href="(\/[^"#?]*)"/g, (all, u) => LINKS[u] ? 'href="' + LINKS[u] + '"' : all);
  // Toggle starts on Spanish.
  h = h.replace('class="lang-opt active" id="btnEN"', 'class="lang-opt" id="btnEN"')
       .replace('class="lang-opt" id="btnES"', 'class="lang-opt active" id="btnES"')
       .replace("let lang = 'en';", "let lang = 'es';")
       .replace(/\n  setLang\('en'\);\n/, "\n  setLang('es');\n");
  // FAQ structured data in Spanish.
  const qa = [];
  for (let i = 1; T.es['faq' + i + '-q']; i++) qa.push({ '@type': 'Question', name: T.es['faq' + i + '-q'], acceptedAnswer: { '@type': 'Answer', text: T.es['faq' + i + '-a'] } });
  if (qa.length) h = h.replace(/<script type="application\/ld\+json" id="faq-ld">[\s\S]*?<\/script>/,
    '<script type="application/ld+json" id="faq-ld">\n' + JSON.stringify({ '@context': 'https://schema.org', '@type': 'FAQPage', inLanguage: 'es', mainEntity: qa }, null, 1) + '\n</script>');
  h = h.replace('<!DOCTYPE html>', '<!DOCTYPE html>\n<!-- Generated by build-es.js from ' + p.src + '. Do not edit by hand. -->');

  const outPath = path.join(root, p.out);
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, h);
  console.log('wrote', p.out, '(' + Object.keys(T.es).length + ' strings)');
}
